<?php
$CFG=require __DIR__.'/config.php';
require_once __DIR__.'/security_controls.php';security_start_session();
try{$guard=new PDO('mysql:host='.$CFG['db_host'].';port='.(int)($CFG['db_port']??3306).';dbname='.$CFG['db_name'].';charset=utf8mb4',$CFG['db_user'],$CFG['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);if((int)$guard->query('SELECT COUNT(*) FROM users')->fetchColumn()>0){http_response_code(403);exit('Already installed. Use the signed-in Admin upgrade. Reinstallation cannot reset accounts.');}}catch(PDOException $e){if(!in_array((int)($e->errorInfo[1]??0),[1049,1146],true)){http_response_code(503);exit('Installation database is unavailable.');}}
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  $pdo=new PDO('mysql:host='.$CFG['db_host'].';charset=utf8mb4',$CFG['db_user'],$CFG['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
  $pdo->exec('CREATE DATABASE IF NOT EXISTS `'.$CFG['db_name'].'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');$pdo->exec('USE `'.$CFG['db_name'].'`');
  $sql=file_get_contents(__DIR__.'/schema.sql');foreach(array_filter(array_map('trim',preg_split('/;\s*(?:\r?\n|$)/',$sql))) as $q)$pdo->exec($q);
  $hash=password_hash('admin123',PASSWORD_DEFAULT);$st=$pdo->prepare("INSERT INTO users(name,username,password_hash,role) VALUES('System Administrator','admin',?,'Admin') ON DUPLICATE KEY UPDATE password_hash=VALUES(password_hash),role='Admin'");$st->execute([$hash]);
  $defaults=['beginning_locked'=>'0','default_lazada_pct'=>'20','default_shopee_pct'=>'40','default_tiktok_pct'=>'40','auto_allocate_inflow'=>'0'];$brands=['RS8','SRF','Oils & Liquid Essentials','Lumina Pro','Merchandise','Belts'];$bst=$pdo->prepare('INSERT IGNORE INTO brands(name,sort_order) VALUES(?,?)');foreach($brands as $i=>$b)$bst->execute([$b,($i+1)*10]);$st=$pdo->prepare('INSERT INTO settings(key_name,value_text) VALUES(?,?) ON DUPLICATE KEY UPDATE value_text=value_text');foreach($defaults as $k=>$v)$st->execute([$k,$v]);
  $count=(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();if($count===0&&file_exists(__DIR__.'/data/seed_products.json')){$items=json_decode(file_get_contents(__DIR__.'/data/seed_products.json'),true)?:[];$ins=$pdo->prepare('INSERT INTO products(name,normalized_name,brand,category,base_uom,low_stock_threshold) VALUES(?,?,?,?,?,?)');foreach($items as $x){$name=$x['name']??$x['Item']??'';if(!$name)continue;$brand=$x['brand']??(preg_match('/^\s*(RS8|SRF|NANOMOLY|LUMINAPRO|LUMINA|BOSS1)\b/i',$name,$m)?strtoupper($m[1]):'Other');$cat=$x['category']??'Uncategorized';$ins->execute([$name,mb_strtolower(trim(preg_replace('/\s+/',' ',$name))),$brand,$cat,'pc',10]);$id=(int)$pdo->lastInsertId();$sku=substr(preg_replace('/[^A-Z0-9]/','',strtoupper($brand)),0,4).'-'.substr(preg_replace('/[^A-Z0-9]/','',strtoupper($cat)),0,4).'-'.str_pad((string)$id,4,'0',STR_PAD_LEFT);$pdo->prepare('UPDATE products SET master_sku=? WHERE id=?')->execute([$sku,$id]);}}

  if(file_exists(__DIR__.'/data/platform_seed.json')){$maps=json_decode(file_get_contents(__DIR__.'/data/platform_seed.json'),true)?:[];$sel=$pdo->prepare('SELECT id FROM products WHERE normalized_name=?');$mapst=$pdo->prepare('INSERT IGNORE INTO platform_aliases(platform,external_id,alias,normalized_alias,product_id) VALUES(?,?,?,?,?)');foreach($maps as $m){$sel->execute([mb_strtolower(trim(preg_replace('/\s+/',' ',$m['product_name'])))]);if($pid=$sel->fetchColumn())$mapst->execute([$m['platform'],$m['external_id']?:null,$m['alias'],mb_strtolower(trim(preg_replace('/\s+/',' ',$m['alias']))),$pid]);}}
  $msg='Installation completed. Admin account reset to admin / admin123.';
 }catch(Throwable $e){$err=$e->getMessage();}
}
$zip=class_exists('ZipArchive');
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" type="image/png" href="assets/logos/rs8.png"><title>RS8 Installer</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth-bg"><div class="auth-card install-card"><img class="auth-logo" src="assets/logos/rs8.png"><h1>E-commerce Inventory Management System</h1><p class="muted">Version 3 Installer</p><?php if(!$zip):?><div class="alert danger">PHP Zip extension (ZipArchive) is required for XLSX imports.</div><?php endif;?><?php if($msg):?><div class="alert success"><?=htmlspecialchars($msg)?></div><a class="btn primary" href="login.php">Go to Login</a><?php elseif($err):?><div class="alert danger"><?=htmlspecialchars($err)?></div><?php endif;?><p>This creates/repairs database tables and seeds the product master.</p><form method="post"><button class="btn primary" <?=$zip?'':'disabled'?>>Install / Repair System</button></form></div></body></html>
